import{_ as i,C as e,o as n,c as l,E as a,a7 as s}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Click2Chat Data Collection","description":"A summary of Click2Chat data practices.","frontmatter":{"title":"Click2Chat Data Collection","description":"A summary of Click2Chat data practices."},"headers":[],"relativePath":"apps/click2chat/data-collection.md","filePath":"apps/click2chat/data-collection.md"}'),d={name:"apps/click2chat/data-collection.md"};function p(h,t,u,m,b,v){const o=e("AppBreadcrumbs"),c=e("AppSubnav"),r=e("CopyStandaloneUrl");return n(),l("div",null,[a(o,{"app-id":"click2chat",current:"Data Collection"}),a(c,{"app-id":"click2chat"}),a(r,{path:"/data-collection/click2chat",label:"Copy standalone data-collection URL","copied-label":"Data-collection URL copied","document-name":"Click2Chat data-collection page"}),t[0]||(t[0]=s('<h1 id="click2chat-data-collection" tabindex="-1">Click2Chat Data Collection <a class="header-anchor" href="#click2chat-data-collection" aria-label="Permalink to &quot;Click2Chat Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 22, 2026</p><h2 id="data-processed-on-the-device" tabindex="-1">Data processed on the device <a class="header-anchor" href="#data-processed-on-the-device" aria-label="Permalink to &quot;Data processed on the device&quot;">​</a></h2><p>Click2Chat processes the phone number, selected country code, and optional draft message that you enter or paste. This information is held temporarily to create the WhatsApp action you request. It is not saved as an app record or sent to the developer.</p><p>The app can store two preferences locally:</p><ul><li>The last selected country</li><li>The selected light, dark, or system theme</li></ul><p>India is used when no country preference has previously been saved. Preferences are stored locally on the device or in the browser.</p><h2 id="clipboard" tabindex="-1">Clipboard <a class="header-anchor" href="#clipboard" aria-label="Permalink to &quot;Clipboard&quot;">​</a></h2><p>Clipboard text is read only after you press the paste button. Click2Chat does not monitor clipboard changes or collect clipboard contents in the background.</p><h2 id="data-received-by-external-services" tabindex="-1">Data received by external services <a class="header-anchor" href="#data-received-by-external-services" aria-label="Permalink to &quot;Data received by external services&quot;">​</a></h2><p>When you initiate a chat, WhatsApp, WhatsApp Business, or <code>wa.me</code> receives the formatted number and optional message required to open the conversation. Their privacy practices apply to that user-initiated transfer.</p><p>The static web host may receive ordinary web request information when the browser version is loaded. Click2Chat has no developer analytics, advertising, tracking, account, or cloud-storage service.</p><h2 id="data-received-by-the-developer" tabindex="-1">Data received by the developer <a class="header-anchor" href="#data-received-by-the-developer" aria-label="Permalink to &quot;Data received by the developer&quot;">​</a></h2><p>The developer does not receive phone numbers, messages, clipboard contents, or local preferences through Click2Chat. A support email contains only the information you choose to send.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',16))])}const y=i(d,[["render",p]]);export{f as __pageData,y as default};
